package uk.ac.ravensbourne.casevault.domain;
import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="case_notes") public class CaseNote { @Id private UUID id; @ManyToOne @JoinColumn(name="case_id") private CaseRecord caseRecord; @ManyToOne @JoinColumn(name="organisation_id") private Organisation organisation; @ManyToOne @JoinColumn(name="author_id") private UserAccount author; @Column(nullable=false) private String body; @Column(name="client_visible") private boolean clientVisible; protected CaseNote(){} public CaseNote(UUID id,CaseRecord c,UserAccount a,String body,boolean visible){this.id=id;caseRecord=c;organisation=c.getOrganisation();author=a;this.body=body;clientVisible=visible;} public String getBody(){return body;} public boolean isClientVisible(){return clientVisible;} }
